  AK.def3d("G1-c", { title: "Diseases of crop groups — causal organisms, symptoms and control", blurb: "Pick a disease. Set the humidity, watch the symptoms develop on the crop, then apply the control measure.", cam: [[1.2, 1.4, 3.2], [0, 0.7, 0]],
    values: { d: "blackpod", ctl: 0 }, vars: [{ key: "rh", label: "Relative humidity", min: 30, max: 100, step: 5, value: 85, unit: "%" }, { key: "wk", label: "Weeks", min: 0, max: 8, value: 4 }],
    controls: [{ type: "select", key: "d", label: "Disease", options: DIS.map((d) => [d[0], d[2] + " — " + d[1]]) }, { type: "toggle", key: "ctl", label: "Apply control measures" }],
    sev(c) { const D = DIS.find((d) => d[0] === c.d), viral = /Virus/.test(D[4]); const rh = viral ? 1 : clamp((c.rh - 40) / 50, 0, 1.1); return clamp(rh * c.wk / 8 * (c.ctl ? 0.25 : 1), 0, 1); },
    build(S, s) { s.key = null; }, update(S, s, c) { const D = DIS.find((d) => d[0] === c.d), sv = MK.scenes["G1-c"].sev(c), k = c.d + Math.round(sv * 10); if (s.key === k) return; s.key = k; const g = BK.group(S, s); AK.ground(g, { w: 7, d: 5, amp: 0.01, fieldFn: () => 1, tex: D[3] === "cocoa" ? "forest_floor" : "farm_soil" }); [-0.6, 0.6].forEach((x, i) => { const big = ["cocoa", "citrus", "coffee"].includes(D[3]); const p = AK.plant(D[3], c.d === "damp" ? 0.15 : 0.85, { seed: 2 + i, roots: c.d === "rootknot" }); p.scale.setScalar(big ? 0.25 : D[3] === "rice" ? 1.4 : D[3] === "onion" ? 1.6 : 0.6); if (i === 0 && sv > 0.05) { tintPlant(p, AK.sickLeaf(D[8], D[9], Math.round(10 + sv * 70), 6 + sv * 10, D[10])); if (c.d === "damp" && sv > 0.5) p.rotation.z = 1.3; if (c.d === "twister") p.rotation.y = sv * 2; if (c.d === "rosette") p.scale.multiplyScalar(1 - sv * 0.5); } p.position.x = x; g.add(p); }); if (c.d === "rootknot" && sv > 0.1) for (let i = 0; i < 14 * sv; i++) { const k2 = AK.sph(0.025, AK.std(0xe8d8b0)); k2.position.set(-0.6 + (Math.random() - 0.5) * 0.3, -0.05 - Math.random() * 0.25, (Math.random() - 0.5) * 0.3); g.add(k2); } if (/Virus/.test(D[4])) { const v = AK.pest(/whitefly/.test(D[5]) ? "thrips" : /aphid/i.test(D[5]) ? "aphid" : "mealybug", 0.25); v.position.set(-0.4, 0.6, 0.3); g.add(v); } },
    labels: (s, c) => [{ id: "s", p: [-0.6, 0.9, 0], t: "Diseased" }, { id: "h", p: [0.6, 0.9, 0], t: "Healthy" }],
    hud: (s, c) => { const D = DIS.find((d) => d[0] === c.d), sv = MK.scenes["G1-c"].sev(c); return [{ title: D[1] + " (" + D[2] + ")", lines: [["Severity " + f(sv * 100, 3) + " %", "#ffd27a", true], "Cause: " + D[4], "Spread: " + D[5], "Symptoms: " + D[6], "Control: " + D[7]] }]; },
    readouts: (s, c) => { const D = DIS.find((d) => d[0] === c.d); return [["Disease", D[1]], ["Organism", D[4].split(" (")[0]], ["Severity", f(MK.scenes["G1-c"].sev(c) * 100, 3) + " %"]]; },
    tasks: ["For every disease, record the causal organism, mode of spread, symptom and control.", "Find two fungal, two viral, two bacterial and one nematode disease.", "Why does humidity not change the severity of viral diseases here?"], draw: GK.fallback("Crop diseases", DIS.slice(0, 8).map((d) => d[1] + " — " + d[4])) });

